{
  "sql": "SELECT p.product_id, p.product_name, SUM(oi.quantity) AS total_quantity FROM commerce.order_items AS oi INNER JOIN commerce.orders AS o ON oi.order_id = o.order_id INNER JOIN commerce.products AS p ON oi.product_id = p.product_id WHERE o.order_date >= $1 AND o.order_date < $2 AND LOWER(o.order_status) NOT IN ('cancelled', 'canceled') GROUP BY p.product_id, p.product_name ORDER BY 3 DESC, p.product_id ASC LIMIT 20",
  "parameters": ["2022-01-01", "2023-01-01"],
  "explanation": "Joins order_items with orders and products to aggregate total quantity sold per product in 2022, excluding cancelled orders. Orders are filtered by date range and status. Results are sorted by total quantity descending, with product_id as a tie-breaker, limited to the top 20."
}

{
  "sql": "SELECT p.category, COUNT(DISTINCT o.order_id) AS order_count FROM commerce.orders AS o INNER JOIN commerce.order_items AS oi ON o.order_id = oi.order_id INNER JOIN commerce.products AS p ON oi.product_id = p.product_id WHERE o.order_date >= $1 AND o.order_date < $2 GROUP BY p.category ORDER BY 1 LIMIT 200",
  "parameters": ["2022-12-01", "2023-01-01"],
  "explanation": "Counts distinct orders containing at least one item from each product category for orders placed in December 2022."
}

{
  "sql": "SELECT p.category AS category, SUM(oi.quantity * oi.unit_price) AS gross_line_value FROM commerce.order_items AS oi INNER JOIN commerce.orders AS o ON oi.order_id = o.order_id INNER JOIN commerce.products AS p ON oi.product_id = p.product_id WHERE o.order_date >= $1 AND o.order_date < $2 GROUP BY p.category ORDER BY 1 LIMIT 200",
  "parameters": ["2022-01-01", "2023-01-01"],
  "explanation": "Calculates the gross line value (quantity * unit_price) for each product category in 2022 by joining order items with orders and products, filtering by the specified date range, and aggregating the sum of line values grouped by category."
}

{
  "sql": "SELECT p.category, SUM(oi.quantity * oi.unit_price - oi.discount_amount) AS net_line_value FROM commerce.order_items AS oi INNER JOIN commerce.orders AS o ON oi.order_id = o.order_id INNER JOIN commerce.products AS p ON oi.product_id = p.product_id WHERE o.order_date >= $1 AND o.order_date < $2 GROUP BY p.category ORDER BY 1 LIMIT 200",
  "parameters": [
    "2022-01-01",
    "2023-01-01"
  ],
  "explanation": "Calculates the net line value (quantity * unit_price - discount_amount) for each product category in 2022 by joining order items with orders and products, filtering by order date, and aggregating by category."
}

{
  "sql": "SELECT p.product_id, p.product_name, SUM(r.return_quantity) AS total_units_returned FROM commerce.products AS p INNER JOIN commerce.returns AS r ON p.product_id = r.product_id WHERE r.return_date >= $1 AND r.return_date < $2 GROUP BY p.product_id, p.product_name ORDER BY 3 DESC, p.product_id ASC LIMIT 10",
  "parameters": [
