{
  "sql": "WITH ordered_units AS (SELECT oi.product_id, SUM(oi.quantity) AS ordered_units FROM commerce.order_items AS oi INNER JOIN commerce.orders AS o ON oi.order_id = o.order_id WHERE o.order_date >= $1 AND o.order_date < $2 AND LOWER(o.order_status) NOT IN ('cancelled', 'canceled') GROUP BY oi.product_id), returned_units AS (SELECT r.product_id, SUM(r.return_quantity) AS returned_units FROM commerce.returns AS r WHERE r.return_date >= $1 AND r.return_date < $2 GROUP BY r.product_id) SELECT p.product_id, p.product_name, ru.returned_units, ou.ordered_units, CAST(ru.returned_units AS NUMERIC) / NULLIF(ou.ordered_units, 0) AS return_ratio FROM commerce.products AS p INNER JOIN returned_units AS ru ON p.product_id = ru.product_id INNER JOIN ordered_units AS ou ON p.product_id = ou.product_id ORDER BY 5 DESC NULLS LAST, 1 LIMIT 200",
  "parameters": [
    "2022-01-01",
    "2023-01-01"
  ],
  "explanation": "Calculates the ratio of returned units to ordered units for each product in 2022. It independently aggregates order quantities (excluding cancelled orders) and return quantities by product, joins them to the products table to get names, computes the ratio, and ranks products by this ratio in descending order."
}

