{
  "sql": "WITH inv_agg AS (SELECT p.category AS category, SUM(i.units_sold) AS inventory_units_sold FROM commerce.inventory AS i INNER JOIN commerce.products AS p ON i.product_id = p.product_id WHERE i.snapshot_date >= $1 AND i.snapshot_date < $2 GROUP BY p.category), ord_agg AS (SELECT p.category AS category, SUM(oi.quantity) AS ordered_quantity FROM commerce.order_items AS oi INNER JOIN commerce.orders AS o ON oi.order_id = o.order_id INNER JOIN commerce.products AS p ON oi.product_id = p.product_id WHERE o.order_date >= $3 AND o.order_date < $4 AND LOWER(o.order_status) NOT IN ('cancelled', 'canceled') GROUP BY p.category) SELECT COALESCE(i.category, o.category) AS category, i.inventory_units_sold, o.ordered_quantity FROM inv_agg AS i FULL JOIN ord_agg AS o ON i.category = o.category ORDER BY 1 LIMIT 200",
  "parameters": [
    "2022-12-01",
    "2023-01-01",
    "2022-12-01",
    "2023-01-01"
  ],
  "explanation": "Aggregates inventory units_sold and ordered quantities independently for December 2022 by category, then joins them to compare the metrics."
}

